		// Group = H16 & ':'
		static int Recognize_Group(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			var p     = pos;
			var r     = 0;
			var state = 3;

			switch (state)
			{
				case 0:
					return p;

				case 1:
					if (p > failure.Position)
						failure.Position = p;

					return -1;

				case 2:
					// ':'
					if (p + 1 > text.Length)
						goto case 1;
					if (text[p + 0] != ':')
						goto case 1;
					p += 1;
					goto case 0;

				case 3:
					// H16
					r = Recognize_H16(text, p, ref failure);

					if (r < 0)
						goto case 1;

					p = r;
					goto case 2;

				default:
					return -1;
			}
		}

		// LS32 = (H16 & ':' & H16 | IPv4)
		static int Recognize_LS32(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			global::System.Span<int> bt = stackalloc int[48];

			var sp    = 0;
			var saved = 0;
			var p     = pos;
			var r     = 0;
			var state = 6;

			while (true)
			{
				switch (state)
				{
					case 0:
						return p;

					case 1:
						if (p > failure.Position)
							failure.Position = p;

						if (sp == 0)
							return -1;

						sp    -= 3;
						state  = bt[sp];
						p      = bt[sp + 1];
						saved  = bt[sp + 2];

						// The one transition whose target is not known until now,
						// and so the one that goes through the switch again.
						continue;

					case 2:
						// IPv4
						r = Recognize_IPv4(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 0;

					case 3:
						// H16
						r = Recognize_H16(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 0;

					case 4:
						// ':'
						if (p + 1 > text.Length)
							goto case 1;
						if (text[p + 0] != ':')
							goto case 1;
						p += 1;
						goto case 3;

					case 5:
						// H16
						r = Recognize_H16(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 4;

					case 6:
						// H16 & ':' & H16 — try this one, or the next
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 2; bt[sp + 1] = p; bt[sp + 2] = 0; sp += 3;
						goto case 5;

					default:
						return -1;
				}
			}
		}

