						// ('/' & Segment)* — one more taken
						c0++;
						goto case 3;

					case 5:
						// ('/' & Segment)* — start counting
						c0 = 0;
						goto case 3;

					case 6:
						// Segment
						r = Recognize_Segment(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 4;

					case 7:
						// '/'
						if (p + 1 > text.Length)
							goto case 1;
						if (text[p + 0] != '/')
							goto case 1;
						p += 1;
						goto case 6;

					default:
						return -1;
				}
			}
		}

		// Segment = (Unreserved | SubDelim | PctEncoded | [':' | '@'])*
		static int Recognize_Segment(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			global::System.Span<int> bt = stackalloc int[48];

			var sp    = 0;
			var saved = 0;
			var p     = pos;
			var r     = 0;
			var c     = '\0';
			var c0    = 0;
			var state = 5;

			while (true)
			{
				switch (state)
				{
					case 0:
						return p;

					case 1:
						if (p > failure.Position)
							failure.Position = p;

						if (sp == 0)
							return -1;

						sp    -= 3;
						state  = bt[sp];
						p      = bt[sp + 1];
						saved  = bt[sp + 2];

						// The one transition whose target is not known until now,
						// and so the one that goes through the switch again.
						continue;

					case 2:
						// (Unreserved | SubDelim | PctEncoded | [':' | '@'])* — stop, and check the count
						c0 = saved;

						goto case 0;

					case 3:
						// (Unreserved | SubDelim | PctEncoded | [':' | '@'])* — take another, or leave stopping open
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 2; bt[sp + 1] = p; bt[sp + 2] = c0; sp += 3;
						goto case 12;

					case 4:
						// (Unreserved | SubDelim | PctEncoded | [':' | '@'])* — one more taken
						c0++;
						goto case 3;

					case 5:
						// (Unreserved | SubDelim | PctEncoded | [':' | '@'])* — start counting
						c0 = 0;
						goto case 3;

					case 6:
						// [':' | '@']
						if (p >= text.Length)
							goto case 1;

						c = text[p];

						if (!(c == ':' || c == '@'))
							goto case 1;

						p++;
						goto case 4;

					case 7:
						// PctEncoded
						r = Recognize_PctEncoded(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 4;

					case 8:
						// PctEncoded — try this one, or the next
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 6; bt[sp + 1] = p; bt[sp + 2] = 0; sp += 3;
						goto case 7;

					case 9:
						// SubDelim
						r = Recognize_SubDelim(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 4;

					case 10:
						// SubDelim — try this one, or the next
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 8; bt[sp + 1] = p; bt[sp + 2] = 0; sp += 3;
						goto case 9;

					case 11:
						// Unreserved
						r = Recognize_Unreserved(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 4;

					case 12:
						// Unreserved — try this one, or the next
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 10; bt[sp + 1] = p; bt[sp + 2] = 0; sp += 3;
						goto case 11;

					default:
						return -1;
				}
			}
		}

		// Rest = (Unreserved | SubDelim | PctEncoded | ['/' | ':' | '?'..'@'])*
		static int Recognize_Rest(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			global::System.Span<int> bt = stackalloc int[48];

			var sp    = 0;
			var saved = 0;
			var p     = pos;
			var r     = 0;
			var c     = '\0';
			var c0    = 0;
			var state = 5;

			while (true)
			{
				switch (state)
				{
					case 0:
						return p;

					case 1:
						if (p > failure.Position)
							failure.Position = p;

						if (sp == 0)
							return -1;

						sp    -= 3;
						state  = bt[sp];
						p      = bt[sp + 1];
						saved  = bt[sp + 2];

						// The one transition whose target is not known until now,
						// and so the one that goes through the switch again.
						continue;

					case 2:
						// (Unreserved | SubDelim | PctEncoded | ['/' | ':' | '?'..'@'])* — stop, and check the count
						c0 = saved;

						goto case 0;

					case 3:
						// (Unreserved | SubDelim | PctEncoded | ['/' | ':' | '?'..'@'])* — take another, or leave stopping open
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 2; bt[sp + 1] = p; bt[sp + 2] = c0; sp += 3;
						goto case 12;

					case 4:
						// (Unreserved | SubDelim | PctEncoded | ['/' | ':' | '?'..'@'])* — one more taken
						c0++;
						goto case 3;

					case 5:
						// (Unreserved | SubDelim | PctEncoded | ['/' | ':' | '?'..'@'])* — start counting
						c0 = 0;
						goto case 3;

					case 6:
						// ['/' | ':' | '?'..'@']
						if (p >= text.Length)
							goto case 1;

						c = text[p];

						if (!(c == '/' || c == ':' || (c >= '?' && c <= '@')))
							goto case 1;

						p++;
						goto case 4;

					case 7:
						// PctEncoded
						r = Recognize_PctEncoded(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 4;

					case 8:
						// PctEncoded — try this one, or the next
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 6; bt[sp + 1] = p; bt[sp + 2] = 0; sp += 3;
						goto case 7;

					case 9:
						// SubDelim
						r = Recognize_SubDelim(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 4;

					case 10:
						// SubDelim — try this one, or the next
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 8; bt[sp + 1] = p; bt[sp + 2] = 0; sp += 3;
						goto case 9;

					case 11:
						// Unreserved
						r = Recognize_Unreserved(text, p, ref failure);

						if (r < 0)
							goto case 1;

						p = r;
						goto case 4;

					case 12:
						// Unreserved — try this one, or the next
						if (sp + 3 > bt.Length) bt = Grow(bt);
						bt[sp] = 10; bt[sp + 1] = p; bt[sp + 2] = 0; sp += 3;
						goto case 11;

					default:
						return -1;
				}
			}
		}

		// PctEncoded = '%' & Hex & Hex
		static int Recognize_PctEncoded(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			var p     = pos;
			var r     = 0;
			var state = 4;

			switch (state)
			{
				case 0:
					return p;

				case 1:
					if (p > failure.Position)
						failure.Position = p;

					return -1;

				case 2:
					// Hex
					r = Recognize_Hex(text, p, ref failure);

					if (r < 0)
						goto case 1;

					p = r;
					goto case 0;

				case 3:
					// Hex
					r = Recognize_Hex(text, p, ref failure);

					if (r < 0)
						goto case 1;

					p = r;
					goto case 2;

				case 4:
					// '%'
					if (p + 1 > text.Length)
						goto case 1;
					if (text[p + 0] != '%')
						goto case 1;
					p += 1;
					goto case 3;

				default:
					return -1;
			}
		}

		// Digit = ['0'..'9']
		static int Recognize_Digit(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			var p     = pos;
			var c     = '\0';
			var state = 2;

			switch (state)
			{
				case 0:
					return p;

				case 1:
					if (p > failure.Position)
						failure.Position = p;

					return -1;

				case 2:
					// ['0'..'9']
					if (p >= text.Length)
						goto case 1;

					c = text[p];

					if (!((c >= '0' && c <= '9')))
						goto case 1;

					p++;
					goto case 0;

				default:
					return -1;
			}
		}

		// Hex = ['0'..'9' | 'A'..'F' | 'a'..'f']
		static int Recognize_Hex(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			var p     = pos;
			var c     = '\0';
			var state = 2;

			switch (state)
			{
				case 0:
					return p;

				case 1:
					if (p > failure.Position)
						failure.Position = p;

					return -1;

				case 2:
					// ['0'..'9' | 'A'..'F' | 'a'..'f']
					if (p >= text.Length)
						goto case 1;

					c = text[p];

					if (!((c >= '0' && c <= '9') || (c >= 'A' && c <= 'F') || (c >= 'a' && c <= 'f')))
						goto case 1;

					p++;
					goto case 0;

				default:
					return -1;
			}
		}

		// Unreserved = ['-'..'.' | '0'..'9' | 'A'..'Z' | '_' | 'a'..'z' | '~']
		static int Recognize_Unreserved(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			var p     = pos;
			var c     = '\0';
			var state = 2;

			switch (state)
			{
				case 0:
					return p;

				case 1:
					if (p > failure.Position)
						failure.Position = p;

					return -1;

				case 2:
					// ['-'..'.' | '0'..'9' | 'A'..'Z' | '_' | 'a'..'z' | '~']
					if (p >= text.Length)
						goto case 1;

					c = text[p];

					if (!((c >= '-' && c <= '.') || (c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || c == '_' || (c >= 'a' && c <= 'z') || c == '~'))
						goto case 1;

					p++;
					goto case 0;

				default:
					return -1;
			}
		}

		// SubDelim = ['!' | '$' | '&'..',' | ';' | '=']
		static int Recognize_SubDelim(global::System.ReadOnlySpan<char> text, int pos, ref Failure failure)
		{
			var p     = pos;
			var c     = '\0';
			var state = 2;

			switch (state)
			{
				case 0:
					return p;

				case 1:
					if (p > failure.Position)
						failure.Position = p;

					return -1;

				case 2:
					// ['!' | '$' | '&'..',' | ';' | '=']
					if (p >= text.Length)
						goto case 1;

					c = text[p];

					if (!(c == '!' || c == '$' || (c >= '&' && c <= ',') || c == ';' || c == '='))
						goto case 1;

					p++;
					goto case 0;

				default:
					return -1;
			}
		}

		/// <summary>What a publication answers with: the value, or why there is none.</summary>
		public readonly struct Match<T>
			where T : class
		{
			private Match(bool isSuccess, T? value, string? error, int position, int length)
			{
				IsSuccess = isSuccess;
				Value     = value;
				Error     = error;
				Position  = position;
				Length    = length;
			}

			/// <summary>Whether there is a value.</summary>
			public bool IsSuccess { get; }

			/// <summary>What was recognized, or null.</summary>
			public T? Value { get; }

			/// <summary>Why nothing was recognized, or null.</summary>
			public string? Error { get; }

			/// <summary>Where the match began, or how far the input could be followed before it failed.</summary>
			public int Position { get; }

			/// <summary>How much was matched. Zero when nothing was.</summary>
			public int Length { get; }

			internal static Match<T> Success(T value, int position, int length)
			{
				return new Match<T>(true, value, null, position, length);
			}

			internal static Match<T> Failed(string error, int position)
			{
				return new Match<T>(false, null, error, position, 0);
			}
		}

		/// <summary>Where a match got before it gave up, and why.</summary>
		struct Failure
		{
			/// <summary>
			/// The furthest position the input was followed to. Zero on a match that
			/// succeeded without ever backtracking, and meaningless unless one failed.
			/// </summary>
			public int Position;
		}

		static int[] Grow(global::System.Span<int> from)
		{
			var bigger = new int[from.Length * 2];

			from.CopyTo(bigger);

			return bigger;
		}
	}
}
